def link_opening_movements_to_their_layer(apps, schema_editor):
    """
    Backfill `InventoryMovement.layer` for every existing OPENING row.

    `set_opening_stock` always created the movement and its layer together,
    one-to-one, before this field existed to record the link -- this ties
    real production data (2026-09-25's 6 onboarded products) to the layer
    it always implicitly belonged to. Purchase/sale movements need no
    backfill: they resolve their layer through purchase_item/sale_item,
    which already existed.
    """
    InventoryMovement = apps.get_model("inventory", "InventoryMovement")
    InventoryLayer = apps.get_model("inventory", "InventoryLayer")
    for movement in InventoryMovement.objects.filter(movement_type="opening", layer__isnull=True):
        layer = InventoryLayer.objects.filter(product_id=movement.product_id, source="opening_stock").first()
        if layer is not None:
            movement.layer = layer
            movement.save(update_fields=["layer"])


